public static void onPlayerLogin(PlayerLoginEvent event) {
        ServerPlayer player = event.getPlayer();
        // Introduce all global waystones to this player
        List<IWaystone> globalWaystones = WaystoneManager.get(player.server).getGlobalWaystones();
        for (IWaystone waystone : globalWaystones) {
            if (!PlayerWaystoneManager.isWaystoneActivated(player, waystone)) {
                PlayerWaystoneManager.activateWaystone(player, waystone);
            }
        }

        WaystoneSyncManager.sendActivatedWaystones(player);
        WaystoneSyncManager.sendWarpPlates(player);
        WaystoneSyncManager.sendWaystoneCooldowns(player);
    }

public static void initialize() {
        Balm.getEvents().onEvent(PlayerLoginEvent.class, LoginHandler::onPlayerLogin);
        Balm.getEvents().onEvent(LivingDamageEvent.class, WarpDamageResetHandler::onDamage);
        Balm.getEvents().onEvent(WaystoneActivatedEvent.class, WaystoneActivationStatHandler::onWaystoneActivated);
    }

public static void onDamage(LivingDamageEvent event) {
        LivingEntity entity = event.getEntity();
        if (entity instanceof Player && entity.getUseItem().getItem() instanceof IResetUseOnDamage) {
            entity.stopUsingItem();
        }
    }

public static void onFOV(FovUpdateEvent event) {
        LivingEntity entity = event.getEntity();
        ItemStack activeItemStack = entity.getUseItem();
        if (isScrollItem(activeItemStack)) {
            float fov = entity.getUseItemRemainingTicks() / 32f * 2f;
            event.setFov((float) Mth.lerp(Minecraft.getInstance().options.fovEffectScale().get(), 1f, fov));
        }
    }

private static boolean isScrollItem(ItemStack activeItemStack) {
        return !activeItemStack.isEmpty() && activeItemStack.getItem() instanceof IFOVOnUse;
    }

public static void onWaystoneActivated(WaystoneActivatedEvent event) {
        event.getPlayer().awardStat(ModStats.waystoneActivated);
    }

