public static <T extends Enum<T>> Codec<T> fromValues(Supplier<T[]> valuesSupplier) {
        final var values = valuesSupplier.get();
        final var nameLookup = createNameLookup(values, Function.identity());
        final var indexLookup = Util.createIndexLookup(Arrays.asList(values));
        return new LenientEnumCodec<>(values, nameLookup, indexLookup);
    }

private static <T extends Enum<T>> Function<String, T> createNameLookup(T[] values, Function<String, String> keyFunction) {
        if (values.length > 16) {
            final var map = Arrays.stream(values)
                    .collect(Collectors.toMap((value) -> keyFunction.apply(getSerializedName(value).toLowerCase(Locale.ROOT)), Function.identity()));
            return (name) -> name == null ? null : map.get(name.toLowerCase(Locale.ROOT));
        } else {
            return (name) -> {
                for (final var value : values) {
                    if (keyFunction.apply(getSerializedName(value)).equalsIgnoreCase(name)) {
                        return value;
                    }
                }

                return null;
            };
        }
    }

private static String getSerializedName(Enum<?> enumValue) {
        if (enumValue instanceof StringRepresentable stringRepresentable) {
            return stringRepresentable.getSerializedName();
        } else {
            return enumValue.name().toLowerCase(Locale.ROOT);
        }
    }

public LenientEnumCodec(S[] values, Function<String, S> nameLookup, ToIntFunction<S> indexLookup) {
            this.codec = ExtraCodecs.orCompressed(BalmCodecs.stringResolver(LenientEnumCodecs::getSerializedName, nameLookup),
                    ExtraCodecs.idResolverCodec(indexLookup, (p_304986_) -> p_304986_ >= 0 && p_304986_ < values.length ? values[p_304986_] : null, -1));
        }

public <T> DataResult<Pair<S, T>> decode(DynamicOps<T> ops, T value) {
            return this.codec.decode(ops, value);
        }

public <T> DataResult<T> encode(S input, DynamicOps<T> ops, T prefix) {
            return this.codec.encode(input, ops, prefix);
        }

public LoadedTableConfig() {
        this(HashBasedTable.create());
    }

public static Pair<LoadedTableConfig, List<Throwable>> of(BalmConfigSchema schema, Table<String, String, Object> table) {
        final var validatedTable = HashBasedTable.<String, String, Object>create();
        final var errors = new ArrayList<Throwable>();
        for (final var rootProperty : schema.rootProperties()) {
            try {
                final var value = validate(rootProperty, table);
                validatedTable.put(rootProperty.category(), rootProperty.name(), value);
            } catch (Throwable e) {
                validatedTable.put(rootProperty.category(), rootProperty.name(), rootProperty.defaultValue());
                errors.add(e);
            }
        }
        for (final var category : schema.categories()) {
            for (final var property : category.properties()) {
                try {
                    final var value = validate(property, table);
                    validatedTable.put(property.category(), property.name(), value);
                } catch (Throwable e) {
                    validatedTable.put(property.category(), property.name(), property.defaultValue());
                    errors.add(e);
                }
            }
        }
        return Pair.of(new LoadedTableConfig(validatedTable), errors);
    }

private static <T> T validate(ConfiguredProperty<T> property, Table<String, String, Object> table) {
        final var value = table.get(property.category(), property.name());
        return property.codec().decode(JsonOps.INSTANCE, GSON.toJsonTree(value)).getOrThrow(false, (error) -> {
        }).getFirst();
    }

@Override
    public <T> void setRaw(ConfiguredProperty<T> property, T value) {
        if (property.type().isAssignableFrom(value.getClass())) {
            table.put(property.category(), property.name(), value);
        } else {
            throw new IllegalArgumentException("Invalid type for property " + property.name() + " in category " + property.category() + ": " + value.getClass()
                    .getName() + ", expected " + property.type().getName());
        }
    }

@Override
    public MutableLoadedConfig copy() {
        return new LoadedTableConfig(HashBasedTable.create(table));
    }

@Override
    public MutableLoadedConfig mutable(BalmConfigSchema schema) {
        return this;
    }

@Override
    @SuppressWarnings("unchecked")
    public <T> T getRaw(ConfiguredProperty<T> property) {
        final var value = table.get(property.category(), property.name());
        if (value == null) {
            return property.defaultValue();
        }
        if (!property.type().isAssignableFrom(value.getClass())) {
            return property.defaultValue();
        }
        return (T) value;
    }

@Override
    public boolean hasProperty(ConfiguredProperty<?> property) {
        return table.contains(property.category(), property.name());
    }

@SuppressWarnings({"rawtypes", "unchecked"})
    default void applyFrom(BalmConfigSchema schema, LoadedConfig config, Predicate<ConfiguredProperty<?>> propertyFilter) {
        for (final var rootProperty : schema.rootProperties()) {
            if (propertyFilter.test(rootProperty)) {
                setRaw((ConfiguredProperty) rootProperty, config.getRaw(rootProperty));
            }
        }
        for (final var category : schema.categories()) {
            for (final var property : category.properties()) {
                if (propertyFilter.test(property)) {
                    setRaw((ConfiguredProperty) property, config.getRaw(property));
                }
            }
        }
    }

default void applyFrom(BalmConfigSchema schema, LoadedConfig config) {
        applyFrom(schema, config, it -> true);
    }

@SuppressWarnings({"rawtypes", "unchecked"})
    public static <T> Codec<T> codec(Class<T> type) {
        if (type == String.class) {
            return (Codec<T>) Codec.STRING;
        } else if (type == Integer.class || type == int.class) {
            return (Codec<T>) IntConfigProperty.CODEC;
        } else if (type == Long.class || type == long.class) {
            return (Codec<T>) LongConfigProperty.CODEC;
        } else if (type == Float.class || type == float.class) {
            return (Codec<T>) FloatConfigProperty.CODEC;
        } else if (type == Double.class || type == double.class) {
            return (Codec<T>) DoubleConfigProperty.CODEC;
        } else if (type == Boolean.class || type == boolean.class) {
            return (Codec<T>) BooleanConfigProperty.CODEC;
        } else if (type == ResourceLocation.class) {
            return (Codec<T>) ResourceLocation.CODEC;
        } else if (type.isEnum()) {
            return enumCodec((Class) type);
        } else {
            throw new IllegalArgumentException("Unsupported nested type: " + type.getName());
        }
    }

private static <T extends Enum<T>> Codec<T> enumCodec(Class<T> type) {
        return LenientEnumCodecs.fromValues(type::getEnumConstants);
    }

@SuppressWarnings({"unchecked", "rawtypes"})
    public static <T> StreamCodec<FriendlyByteBuf, T> streamCodec(Class<T> type) {
        if (type == String.class) {
            return (StreamCodec<FriendlyByteBuf, T>) ByteBufCodecs.STRING_UTF8;
        } else if (type == Integer.class || type == int.class) {
            return (StreamCodec<FriendlyByteBuf, T>) ByteBufCodecs.INT;
        } else if (type == Long.class || type == long.class) {
            return (StreamCodec<FriendlyByteBuf, T>) ByteBufCodecs.LONG;
        } else if (type == Float.class || type == float.class) {
            return (StreamCodec<FriendlyByteBuf, T>) ByteBufCodecs.FLOAT;
        } else if (type == Double.class || type == double.class) {
            return (StreamCodec<FriendlyByteBuf, T>) ByteBufCodecs.DOUBLE;
        } else if (type == Boolean.class || type == boolean.class) {
            return (StreamCodec<FriendlyByteBuf, T>) ByteBufCodecs.BOOL;
        } else if (type == ResourceLocation.class) {
            return (StreamCodec<FriendlyByteBuf, T>) ByteBufCodecs.RESOURCE_LOCATION;
        } else if (type.isEnum()) {
            return enumStreamCodec((Class) type);
        } else {
            throw new IllegalArgumentException("Unsupported nested type: " + type.getName());
        }
    }

private static <T extends Enum<T>> StreamCodec<FriendlyByteBuf, T> enumStreamCodec(Class<T> type) {
        final var byIdMapper = ByIdMap.continuous(Enum::ordinal, type.getEnumConstants(), ByIdMap.OutOfBoundsStrategy.ZERO);
        return ByteBufCodecs.idMapper(byIdMapper, Enum::ordinal);
    }

@Override
    public <T> void setRaw(ConfiguredProperty<T> property, T value) {
        try {
            final var holder = locatePropertyHolder(property);
            final var field = holder.getClass().getField(property.name());
            field.set(holder, value);
        } catch (NoSuchFieldException | IllegalAccessException e) {
            throw new RuntimeException("Failed to set config property '" +
                    (property.category().isEmpty() ? "" : property.category() + ".") +
                    property.name() + "'", e);
        }
    }

@Override
    public <T> T getRaw(ConfiguredProperty<T> property) {
        try {
            final var holder = locatePropertyHolder(property);
            final var field = holder.getClass().getField(property.name());
            @SuppressWarnings("unchecked")
            T value = (T) field.get(holder);
            return value;
        } catch (NoSuchFieldException | IllegalAccessException e) {
            throw new RuntimeException("Failed to get config property '" +
                    (property.category().isEmpty() ? "" : property.category() + ".") +
                    property.name() + "'", e);
        }
    }

