        return energy;
    }

public void setEnergy(int energy) {
        this.energy = energy;
    }

public int getCapacity() {
        return capacity;
    }

public boolean canDrain() {
        return maxDrain > 0;
    }

public boolean canFill() {
        return maxFill > 0;
    }

