public void consumeWhitespace() {
        while (i < input.length()) {
            char c = input.charAt(i);
            if (c == ' ' || c == '\t' || c == '\r') {
                i++;
            } else if (c == '\n') {
                i++;
                line++;
            } else {
                break;
            }
        }
    }

public String peek(int i) {
        return input.substring(this.i, Math.min(this.i + i, input.length()));
    }

public boolean next(String... find) {
        for (String s : find) {
            if (input.startsWith(s, i)) {
                return true;
            }
        }
        return false;
    }

public boolean nextConsume(String... find) {
        for (String s : find) {
            if (input.startsWith(s, i)) {
                i += s.length();
                return true;
            }
        }
        return false;
    }

public String readUntil(String... find) {
        int start = i;
        while (i < input.length()) {
            if (input.charAt(i) == '\n') {
                line++;
            }
            for (String s : find) {
                if (input.startsWith(s, i)) {
                    return input.substring(start, i);
                }
            }
            i++;
        }
        return input.substring(start);
    }

public String readUntilConsume(String... find) {
        int start = i;
        while (i < input.length()) {
            if (input.charAt(i) == '\n') {
                line++;
            }
            for (String s : find) {
                if (input.startsWith(s, i)) {
                    String read = input.substring(start, i);
                    i += s.length();
                    return read;
                }
            }
            i++;
        }
        return input.substring(start);
    }

public String readQuoted() {
        char quote = input.charAt(i);
        if (quote != '"' && quote != '\'') {
            throw new IllegalStateException("Expected a quote character at the start of the string");
        }
        i++; // consume the starting quote

        StringBuilder sb = new StringBuilder();
        while (i < input.length()) {
            char current = input.charAt(i);
            if (current == '\\') { // it is an escape character
                if (i + 1 < input.length()) {
                    char nextChar = input.charAt(i + 1);
                    if (nextChar == quote) { // it is an escaped quote
                        sb.append(nextChar);
                        i += 2; // consume both escape character and quote
                        continue;
                    }
                }
            } else if (current == quote) { // closing quote
                i++; // consume closing quote
                return sb.toString();
            } else if (current == '\n') {
                // Technically we could throw, but we may as well be lenient
                // throw new IllegalArgumentException("Expected closing quote before end of line");
                return sb.toString();
            }
            sb.append(current);
            i++;
        }
        // Technically we could throw, but we may as well be lenient
        // throw new IllegalArgumentException("Expected closing quote before end of file");
        return sb.toString();
    }

public int getLine() {
        return line;
    }

public boolean canRead() {
        return i < input.length();
    }

public int getIndex() {
        return i;
    }

public void revertTo(int index) {
        while (i > index) {
            i--;
            if (input.charAt(i) == '\n') {
                line--;
            }
        }
    }

public static Notoml parse(String input) {
        Notoml result = new Notoml();
        var stateMachine = new NotomlStateMachine();
        var parseBuffer = new NotomlParseBuffer(input);
        var tokenConsumer = new NotomlTokenConsumer() {
            @Override
            public void onPropertyParsed(String category, String property, Object value) {
                result.setProperty(category, property, value);
            }

            @Override
            public void onCommentParsed(String category, String property, String comment) {
                result.setComment(category, property, comment);
            }

            @Override
            public void onError(NotomlError error) {
                result.addError(error);
            }
        };
        while (parseBuffer.canRead()) {
            if (!stateMachine.next(parseBuffer, tokenConsumer)) {
                break;
            }
        }
        return result;
    }

@Override
            public void onPropertyParsed(String category, String property, Object value) {
                result.setProperty(category, property, value);
            }

@Override
            public void onCommentParsed(String category, String property, String comment) {
                result.setComment(category, property, comment);
            }

@Override
            public void onError(NotomlError error) {
                result.addError(error);
            }

@Override
        void next(NotomlStateMachine state, NotomlParseBuffer buffer, NotomlTokenConsumer consumer) {
            buffer.consumeWhitespace();
            if (buffer.nextConsume("[")) {
                state.transition(Category);
            } else if (buffer.nextConsume("#")) {
                state.transition(Comment);
            } else {
                state.transition(Property);
            }
        }

@Override
        void next(NotomlStateMachine state, NotomlParseBuffer buffer, NotomlTokenConsumer consumer) {
            String categoryName = buffer.readUntilConsume("]").trim();
            if (categoryName.isEmpty()) {
                throw new IllegalArgumentException("Expected a category name");
            }
            consumer.emitCategory(categoryName);
            state.transition(None);
        }

@Override
        void next(NotomlStateMachine state, NotomlParseBuffer buffer, NotomlTokenConsumer consumer) {
            String comment = buffer.readUntilConsume("\n", "\r\n", "\r").trim();
            consumer.emitComment(comment);
            state.transition(None);
        }

@Override
        void next(NotomlStateMachine state, NotomlParseBuffer buffer, NotomlTokenConsumer consumer) {
            String property = buffer.readUntilConsume("=", "\n", "\r\n", "\r").trim();
            if (!PROPERTY_KEY_PATTERN.matcher(property).matches()) {
                throw new IllegalStateException("Invalid property key '" + property + "' (properties may only contain letters, numbers, dashes and underscores)");
            }
            consumer.emitPropertyKey(property);
            state.transition(PropertyValue);
        }

@Override
        void next(NotomlStateMachine state, NotomlParseBuffer buffer, NotomlTokenConsumer consumer) {
            buffer.consumeWhitespace();
            if (buffer.nextConsume("\"\"\"")) {
                consumer.emitMultiLineStringStart();
                state.transition(MultiLineString);
            } else if (buffer.next("\"", "'")) {
                String value = buffer.readQuoted();
                consumer.emitPropertyValue(value);
                state.transition(None);
            } else if (buffer.nextConsume("[")) {
                consumer.emitListStart();
                state.transition(List);
            } else {
                String value = buffer.readUntilConsume("\n", "\r\n", "\r");
                consumer.emitPropertyValue(value);
                state.transition(None);
            }
        }

@Override
        void next(NotomlStateMachine state, NotomlParseBuffer buffer, NotomlTokenConsumer consumer) {
            if (buffer.nextConsume("\"\"\"")) {
                consumer.emitMultiLineStringEnd();
                state.transition(None);
            } else {
                int start = buffer.getIndex();
                int line = buffer.getLine();
                consumer.emitPropertyValue(buffer.readUntil("\"\"\""));
                if (!buffer.next("\"\"\"")) {
                    consumer.emitError(new NotomlError("Expected \"\"\" to end multi-line string").at(line));
                    buffer.revertTo(start);
                    buffer.readUntil("\n", "\r\n");
                    state.transition(None);
                }
            }
        }

@Override
        void next(NotomlStateMachine state, NotomlParseBuffer buffer, NotomlTokenConsumer consumer) {
            buffer.consumeWhitespace();
            if (buffer.nextConsume("]")) {
                consumer.emitListEnd();
                state.transition(None);
            } else if (buffer.nextConsume(",")) {
                state.transition(ListItem);
            } else {
                state.transition(ListItem);
            }
        }

@Override
        void next(NotomlStateMachine state, NotomlParseBuffer buffer, NotomlTokenConsumer consumer) {
            buffer.consumeWhitespace();
            if (buffer.nextConsume("#")) {
                String value = buffer.readUntil("\n", "\r\n", "\r").trim();
                consumer.emitComment(value);
                state.transition(List);
            } else if (buffer.next("\"", "'")) {
                String value = buffer.readQuoted();
                consumer.emitPropertyValue(value);
                state.transition(List);
            } else {
                String value = buffer.readUntil(",", "]").trim();
                consumer.emitPropertyValue(value);
                state.transition(List);
            }
        }

public static void serialize(Writer writer, Notoml notoml) throws IOException {
        writer.write(serializeToString(notoml));
    }

private static String serializeToString(Notoml notoml) {
        StringBuilder sb = new StringBuilder();

        var data = notoml.getProperties();
        var comments = notoml.getComments();
        var sortedCategoryKeys = data.rowKeySet().stream().sorted().toList();
        for (String category : sortedCategoryKeys) {
            String categoryComment = comments.get(category, "");
            if (categoryComment != null && !categoryComment.isEmpty()) {
                sb.append("\n").append("# ").append(categoryComment).append("\n");
            }

            if (!category.isEmpty()) {
                sb.append("[").append(category).append("]").append("\n");
            }

            Map<String, Object> categoryProperties = data.row(category);
            var sortedPropertyKeys = categoryProperties.keySet().stream().sorted().toList();
            for (String property : sortedPropertyKeys) {
                String propertyComment = comments.get(category, property);
                if (propertyComment != null && !propertyComment.isEmpty()) {
                    sb.append("\n").append("# ").append(propertyComment).append("\n");
                }

                sb.append(property).append(" = ");

                Object value = categoryProperties.get(property);
                if (value instanceof String stringValue) {
                    if (stringValue.contains("\n")) {
                        sb.append("\"\"\"\n").append(value).append("\n\"\"\"");
                    } else {
                        sb.append("\"").append(stringValue.replace("\"", "\\\"")).append("\"");
                    }
                } else if (value instanceof List<?> listValue) {
                    serializeList(listValue, sb);
                } else if (value instanceof Enum<?> enumValue) {
                    sb.append("\"").append(enumValue.name()).append("\"");
                } else {
                    sb.append(value);
                }

                sb.append("\n");
            }
            sb.append("\n");
        }
        return sb.toString();
    }

private static String serializeList(List<?> list, StringBuilder sb) {
        sb.append("[ ");
        boolean newLines = list.size() > 3;
        if (newLines) {
            sb.append("\n");
        }
        for (int i = 0; i < list.size(); i++) {
            if (newLines) {
                sb.append("    ");
            }
            if (list.get(i) instanceof String) {
                sb.append("\"").append(((String) list.get(i)).replace("\"", "\\\"")).append("\"");
            } else if (list.get(i) instanceof Enum<?>) {
                sb.append("\"").append(((Enum<?>) list.get(i)).name()).append("\"");
            } else {
                sb.append(list.get(i));
            }
            if (i != list.size() - 1) {
                sb.append(", ");
            }
            if (newLines) {
                sb.append("\n");
            }
        }
        sb.append(" ]");
        return sb.toString();
    }

public void transition(NotomlParserState state) {
        this.state = state;
    }

public void end() {
        state = null;
    }

public boolean next(NotomlParseBuffer buffer, NotomlTokenConsumer consumer) {
        try {
            state.next(this, buffer, consumer);
        } catch (Exception e) {
            consumer.emitError(new NotomlError(e.getMessage()).at(buffer.getLine()));
            buffer.readUntil("\n");
            state = NotomlParserState.None;
        }
        return state != null;
    }

public void emitComment(String comment) {
        if (currentComment == null) {
            currentComment = new StringBuilder();
        }
        currentComment.append(comment).append("\n");
    }

public void emitCategory(String categoryName) {
        currentCategory = categoryName;
        if (currentComment != null) {
            onCommentParsed(currentCategory, currentProperty, currentComment.toString());
            currentComment = null;
        }
    }

public void emitPropertyKey(String property) {
        currentProperty = property;
        if (currentComment != null) {
            onCommentParsed(currentCategory, currentProperty, currentComment.toString());
            currentComment = null;
        }
    }

public void emitPropertyValue(String value) {
        if (currentList != null) {
            currentList.add(value);
        } else if (currentMultiLineString != null) {
            currentMultiLineString.append(value);
        } else {
            onPropertyParsed(currentCategory, currentProperty, value);
        }
    }

public void emitListStart() {
        currentList = new ArrayList<>();
    }

public void emitListEnd() {
        onPropertyParsed(currentCategory, currentProperty, currentList);
        currentList = null;
    }

public void emitMultiLineStringStart() {
        currentMultiLineString = new StringBuilder();
    }

public void emitMultiLineStringEnd() {
        onPropertyParsed(currentCategory, currentProperty, currentMultiLineString.toString().trim());
        currentMultiLineString = null;
    }

public void emitError(NotomlError error) {
        onError(error);
    }

