private LoadedConfig loadConfigFromConfigFile(BalmConfigSchema schema) {
        final var configFile = getConfigFile(schema);
        LoadedConfig config = schema.defaults();
        if (configFile.exists()) {
            try {
                config = FabricConfigLoader.load(configFile, schema);
            } catch (IOException e) {
                logger.error("Failed to load config file {}", configFile, e);
            }
        } else {
            try {
                FabricConfigSaver.save(configFile, schema, schema.defaults());
            } catch (IOException e) {
                logger.error("Failed to generate config file {}", configFile, e);
            }
        }
        return config;
    }

public static LoadedConfig load(File configFile, BalmConfigSchema schema) throws IOException {
        Notoml notoml = new Notoml();
        if (configFile.exists()) {
            try {
                String input = Files.readString(configFile.toPath());
                notoml = NotomlParser.parse(input);
            } catch (IOException e) {
                logger.error("Failed to load config file {}", configFile, e);
            }
        }
        final var table = notoml.getProperties();
        final var configAndErrors = LoadedTableConfig.of(schema, table);
        final var config = configAndErrors.getFirst();
        for (final var throwable : configAndErrors.getSecond()) {
            notoml.addError(new NotomlError(throwable.getMessage(), throwable));
        }
        if (notoml.hasErrors()) {
            logger.error("Errors were encountered when loading the config file {}:", configFile.getName());
            for (NotomlError error : notoml.getErrors()) {
                if (error.hasLine()) {
                    logger.error("- {} near line {}", error.getMessage(), error.getLine(), error.getCause());
                } else {
                    logger.error("- {}", error.getMessage(), error.getCause());
                }
            }
            File backupFile = getBackupConfigFile(configFile);
            configFile.renameTo(backupFile);
            FabricConfigSaver.save(configFile, schema, config);
            logger.error("The affected properties have been reset to their defaults and a backup of the corrupted version was created under {}",
                    backupFile.getName());
        } else {
            Notoml updated = FabricConfigSaver.toNotoml(schema, config);
            if (!notoml.containsProperties(updated)) {
                logger.info("The config file {} is missing some properties.", configFile.getName());
                File backupFile = getBackupConfigFile(configFile);
                configFile.renameTo(backupFile);
                FabricConfigSaver.save(configFile, schema, config);
                logger.info("The missing properties have been added and a backup of the previous version was created under {}", backupFile.getName());
            }
        }
        return config;
    }

private static File getBackupConfigFile(File configFile) {
        // Find first non-existing file with the same name ending in .bak.1, .bak.2, etc.
        File backupFile;
        int i = 1;
        do {
            backupFile = new File(configFile.getParentFile(), configFile.getName() + ".bak" + i);
            i++;
        } while (backupFile.exists());
        return backupFile;
    }

private static String getExpectedValueTypeMessage(Class<?> type, Class<?> innerType) {
        if (type == Integer.class || type == Integer.TYPE) {
            return "integer";
        } else if (type == Long.class || type == Long.TYPE) {
            return "integer";
        } else if (type == Double.class || type == Double.TYPE || type == Float.class || type == Float.TYPE) {
            return "floating point number";
        } else if (type == Boolean.class || type == Boolean.TYPE) {
            return "boolean (true or false)";
        } else if (type == String.class) {
            return "string";
        } else if (type == List.class) {
            return "list of " + getExpectedValueTypeMessage(innerType, null);
        } else if (Enum.class.isAssignableFrom(type)) {
            Enum<?>[] enumConstants = (Enum<?>[]) type.getEnumConstants();
            return "enum value (" + String.join(", ", Arrays.stream(enumConstants).map(Enum::name).toArray(String[]::new)) + ")";
        }
        return null;
    }

private static Object convertValue(Object value, Class<?> type, Class<?> innerType) {
        if (type == Integer.class || type == Integer.TYPE) {
            if (value instanceof Number) {
                return ((Number) value).intValue();
            } else if (value instanceof String) {
                try {
                    return Integer.parseInt((String) value);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid integer value: '" + value + "'", e);
                }
            }
        } else if (type == Long.class || type == Long.TYPE) {
            if (value instanceof Number) {
                return ((Number) value).longValue();
            } else if (value instanceof String) {
                try {
                    return Long.parseLong((String) value);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid integer value: '" + value + "'", e);
                }
            }
        } else if (type == Double.class || type == Double.TYPE) {
            if (value instanceof Number) {
                return ((Number) value).doubleValue();
            } else if (value instanceof String stringValue) {
                try {
                    return Double.parseDouble(stringValue.replace(',', '.'));
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid floating point value: '" + value + "'", e);
                }
            }
        } else if (type == Float.class || type == Float.TYPE) {
            if (value instanceof Number) {
                return ((Number) value).floatValue();
            } else if (value instanceof String stringValue) {
                try {
                    return Float.parseFloat(stringValue.replace(',', '.'));
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid floating point value: '" + value + "'", e);
                }
            }
        } else if (type == String.class) {
            if (value instanceof String) {
                return value;
            } else {
                return value.toString();
            }
        } else if (type == Boolean.class || type == Boolean.TYPE) {
            if (value instanceof Number) {
                return ((Number) value).intValue() != 0;
            } else if (value instanceof String stringValue) {
                if (stringValue.equalsIgnoreCase("true")) {
                    return true;
                } else if (stringValue.equalsIgnoreCase("false")) {
                    return false;
                } else {
                    throw new IllegalArgumentException("Invalid boolean value: '" + value + "'");
                }
            } else if (value instanceof Boolean) {
                return value;
            }
        } else if (type == List.class) {
            if (value instanceof List<?>) {
                List<?> list = (List<?>) value;
                List<Object> convertedList = new ArrayList<>();
                for (Object entry : list) {
                    Object convertedEntry = convertValue(entry, innerType, null);
                    if (convertedEntry != null) {
                        convertedList.add(convertedEntry);
                    }
                }
                return convertedList;
            } else if (value.getClass() == innerType) {
                List<Object> list = new ArrayList<>();
                list.add(value);
                return list;
            } else {
                throw new IllegalArgumentException("Invalid list value: '" + value + "'");
            }
        } else if (Enum.class.isAssignableFrom(type)) {
            if (value instanceof String) {
                try {
                    return parseEnumValue(type, (String) value);
                } catch (IllegalArgumentException e) {
                    throw new IllegalArgumentException("Invalid enum value: '" + value + "'", e);
                }
            } else {
                throw new IllegalArgumentException("Invalid enum value: '" + value + "'");
            }
        }
        return null;
    }

private static Object parseEnumValue(Class<?> type, String value) {
        for (Object enumConstant : type.getEnumConstants()) {
            if (enumConstant.toString().equalsIgnoreCase(value)) {
                return enumConstant;
            }
        }

        return null;
    }

public static Notoml toNotoml(BalmConfigSchema schema, LoadedConfig config) {
        Table<String, String, Object> properties = HashBasedTable.create();
        Table<String, String, String> comments = HashBasedTable.create();
        for (final var rootProperty : schema.rootProperties()) {
            final var value = config.getRaw(rootProperty);
            properties.put("", rootProperty.name(), value);
            comments.put("", rootProperty.name(), rootProperty.comment());
        }
        for (final var category : schema.categories()) {
            comments.put(category.name(), "", category.comment());
            for (final var property : category.properties()) {
                final var value = config.getRaw(property);
                properties.put(property.category(), property.name(), value);
                comments.put(property.category(), property.name(), property.comment());
            }
        }
        return new Notoml(properties, comments);
    }

public static void save(File configFile, BalmConfigSchema schema, LoadedConfig config) throws IOException {
        var notoml = toNotoml(schema, config);
        try (FileWriter writer = new FileWriter(configFile)) {
            NotomlSerializer.serialize(writer, notoml);
        }
    }

