            if (customFarmBlock.canSustainPlant(state, blockGetter, pos, Direction.UP, block)) {
                if (customFarmBlock.isFertile(state, blockGetter, pos)) {
                    return 3f;
                } else {
                    return 1f;
                }
            }
        }

        return g;
    }

